sealed interface PaymentState
data class Pending(val initiatedBy: String) : PaymentState
data class Approved(val approvedBy: String) : PaymentState

@PreAuthorize("hasAuthority('payment:release')")
fun release(id: PaymentId) = withLock(id) { req ->
    val st = req.state
    check(st is Pending && st.initiatedBy != currentPrincipal()) { "approver must differ from initiator" }
    req.state = Approved(currentPrincipal())
}
